// THREE-STEP MEMOISATION TEMPLATE
// Step 1: check cache
// Step 2: compute recursively (same as brute force)
// Step 3: store in cache and return

// FIBONACCI with memoisation: O(n) time, O(n) space
function fib(n, memo = new Map()) {
    if (n <= 1) return n;                    // base case
    if (memo.has(n)) return memo.get(n);     // STEP 1: cache hit
    const result = fib(n-1, memo) + fib(n-2, memo); // STEP 2: compute
    memo.set(n, result);                     // STEP 3: store
    return result;
}
// fib(10): each of fib(0)..fib(10) computed exactly once -> 11 calls total
// Without memo: 2^10 = 1024 calls

// COIN CHANGE with memoisation: minimum coins to make amount
function coinChange(coins, amount, memo = new Map()) {
    if (amount === 0) return 0;              // base: no coins needed
    if (amount < 0)  return Infinity;        // base: invalid
    if (memo.has(amount)) return memo.get(amount); // cache hit

    let minCoins = Infinity;
    for (const coin of coins) {
        // Try using this coin: remaining = amount - coin
        const sub = coinChange(coins, amount - coin, memo);
        if (sub !== Infinity) {
            minCoins = Math.min(minCoins, 1 + sub);
        }
    }
    memo.set(amount, minCoins);              // store
    return minCoins;
}
// coinChange([1,2,5], 11) -> 3 (5+5+1)
// Unique subproblems: amounts 0..11 = 12 subproblems
// Work per subproblem: O(coins.length) = O(3)
// Total: O(amount * coins.length) = O(11 * 3) = O(33)

// 2D MEMOISATION: grid path counting
function uniquePaths(m, n, memo = new Map()) {
    const key = `${m},${n}`;
    if (m === 1 || n === 1) return 1;        // base: only one path along edge
    if (memo.has(key)) return memo.get(key); // cache hit
    const result = uniquePaths(m-1, n, memo) + uniquePaths(m, n-1, memo);
    memo.set(key, result);
    return result;
}
// uniquePaths(3,7) -> 28
// Unique subproblems: m*n = 21
// Total: O(m*n)

