// FIBONACCI: top-down -> bottom-up conversion

// Top-down (memo): natural but O(n) call stack
// Bottom-up: iterative, O(n) space initially
function fib_bottomUp(n) {
    if (n <= 1) return n;
    const dp = new Array(n + 1);
    dp[0] = 0; dp[1] = 1;           // base cases
    for (let i = 2; i <= n; i++) {
        dp[i] = dp[i-1] + dp[i-2]; // transition
    }
    return dp[n];
}
// Space: O(n) for the dp array

// SPACE OPTIMISED: O(1) — only two previous values needed
function fib_optimal(n) {
    if (n <= 1) return n;
    let prev2 = 0, prev1 = 1;
    for (let i = 2; i <= n; i++) {
        const curr = prev1 + prev2;
        prev2 = prev1;              // slide window
        prev1 = curr;
    }
    return prev1;
}
// Space: O(1) — only two variables regardless of n

// COIN CHANGE: top-down -> bottom-up
function coinChange_bottomUp(coins, amount) {
    // dp[i] = minimum coins to make amount i
    const dp = new Array(amount + 1).fill(Infinity);
    dp[0] = 0; // base case: 0 coins to make amount 0

    for (let amt = 1; amt <= amount; amt++) {
        for (const coin of coins) {
            if (coin <= amt && dp[amt - coin] !== Infinity) {
                dp[amt] = Math.min(dp[amt], 1 + dp[amt - coin]);
            }
        }
    }
    return dp[amount] === Infinity ? -1 : dp[amount];
}
// dp[1..amount] filled left to right
// Each dp[amt] uses dp[amt-coin] which was filled earlier (amt-coin < amt)
// This topological order is correct: smaller amounts before larger

console.log(fib_optimal(10));                // 55
console.log(coinChange_bottomUp([1,2,5], 11)); // 3 (5+5+1)

// COMPARISON: top-down vs bottom-up for same problem
// Top-down:   O(n) time, O(n) space (cache) + O(n) space (call stack)
// Bottom-up:  O(n) time, O(n) space (table), no call stack
// Optimised:  O(n) time, O(1) space, no call stack — best for 1D recurrence

