// CLIMBING STAIRS (#70) — O(n) time, O(1) space
function climbStairs(n) {
    if (n <= 2) return n;
    let prev2 = 1, prev1 = 2; // dp[1]=1, dp[2]=2
    for (let i = 3; i <= n; i++) {
        const curr = prev1 + prev2;
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}
// climbStairs(4): 1,2,3,5 -> 5 ways
// dp[3]=dp[2]+dp[1]=2+1=3, dp[4]=dp[3]+dp[2]=3+2=5

// MIN COST CLIMBING STAIRS (#746) — choose which step to leave from
function minCostClimbingStairs(cost) {
    const n = cost.length;
    const dp = new Array(n + 1).fill(0); // dp[n] = min cost to reach step n (top)
    // dp[0]=0, dp[1]=0: can start at step 0 or 1 for free
    for (let i = 2; i <= n; i++) {
        // Come from step i-1 (pay cost[i-1]) or step i-2 (pay cost[i-2])
        dp[i] = Math.min(dp[i-1] + cost[i-1], dp[i-2] + cost[i-2]);
    }
    return dp[n]; // cost to reach the top (beyond the last step)
}
// cost=[10,15,20]: dp=[0,0,10,15,20] -> dp[3] at top
// dp[2]=min(0+10, 0+15)=10. dp[3]=min(10+15, 0+20)=20. Answer=20? No:
// dp[3]=min(dp[2]+cost[2], dp[1]+cost[1])=min(10+20,0+15)=15

// DECODE WAYS (#91) — conditional Fibonacci with char validation
function numDecodings(s) {
    const n = s.length;
    if (s[0] === '0') return 0; // leading zero: no valid decoding
    const dp = new Array(n + 1).fill(0);
    dp[0] = 1; // empty string: 1 way
    dp[1] = 1; // first char: 1 way (already checked non-zero)

    for (let i = 2; i <= n; i++) {
        // Single digit: s[i-1] is '1'-'9'
        if (s[i-1] !== '0') dp[i] += dp[i-1];
        // Two digits: s[i-2..i-1] is '10'-'26'
        const twoDigit = Number(s.slice(i-2, i));
        if (twoDigit >= 10 && twoDigit <= 26) dp[i] += dp[i-2];
    }
    return dp[n];
}
// '226': dp=[1,1,2,3] -> 3 ways: (2,2,6),(22,6),(2,26)
// '06':  returns 0 immediately (leading zero)

console.log(climbStairs(5));                     // 8
console.log(minCostClimbingStairs([10,15,20]));  // 15
console.log(numDecodings('226'));                 // 3

