// HOUSE ROBBER I (#198) — O(n) time, O(1) space
function rob(nums) {
    if (nums.length === 1) return nums[0];
    let prev2 = nums[0];                         // dp[i-2]
    let prev1 = Math.max(nums[0], nums[1]);      // dp[i-1]

    for (let i = 2; i < nums.length; i++) {
        const curr = Math.max(prev1, prev2 + nums[i]); // skip or rob
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}
// [2,7,9,3,1]: dp[0]=2, dp[1]=7, dp[2]=max(7,2+9)=11,
//              dp[3]=max(11,7+3)=11, dp[4]=max(11,11+1)=12
// Answer: 12 (rob houses 0,2,4: 2+9+1=12)
console.log(rob([2,7,9,3,1])); // 12

// HOUSE ROBBER II (#213) — circular array, O(n) time O(1) space
function rob2(nums) {
    if (nums.length === 1) return nums[0];
    if (nums.length === 2) return Math.max(nums[0], nums[1]);

    // Helper: linear rob on a subarray
    function linearRob(arr) {
        let prev2 = arr[0], prev1 = Math.max(arr[0], arr[1]);
        for (let i = 2; i < arr.length; i++) {
            const curr = Math.max(prev1, prev2 + arr[i]);
            prev2 = prev1; prev1 = curr;
        }
        return prev1;
    }

    // Case 1: exclude last house (consider houses 0..n-2)
    // Case 2: exclude first house (consider houses 1..n-1)
    return Math.max(
        linearRob(nums.slice(0, nums.length - 1)), // exclude last
        linearRob(nums.slice(1))                    // exclude first
    );
}
// [2,3,2]: exclude last -> [2,3]: max=3. exclude first -> [3,2]: max=3. Answer=3
// [1,2,3,1]: exclude last -> [1,2,3]: max=4. exclude first -> [2,3,1]: max=3. Answer=4
console.log(rob2([2,3,2]));    // 3
console.log(rob2([1,2,3,1]));  // 4

// HOUSE ROBBER III (trees) — preview of tree DP in Level 2
// Each node can be robbed, but not its children
// dp[node] = [rob this node, skip this node]
function rob3(root) {
    function dfs(node) {
        if (!node) return [0, 0];
        const [leftRob, leftSkip]   = dfs(node.left);
        const [rightRob, rightSkip] = dfs(node.right);
        // Rob this: skip both children
        const robThis  = node.val + leftSkip + rightSkip;
        // Skip this: take best from each child independently
        const skipThis = Math.max(leftRob, leftSkip) + Math.max(rightRob, rightSkip);
        return [robThis, skipThis];
    }
    return Math.max(...dfs(root));
}

