// LONGEST PALINDROMIC SUBSTRING (#5) — expand-around-centre
// O(n^2) time, O(1) space
function longestPalindrome(s) {
    let start = 0, maxLen = 1;

    function expand(left, right) {
        while (left >= 0 && right < s.length && s[left] === s[right]) {
            if (right - left + 1 > maxLen) {
                maxLen = right - left + 1;
                start  = left;
            }
            left--; right++;
        }
    }

    for (let i = 0; i < s.length; i++) {
        expand(i, i);     // odd-length palindromes (centre at i)
        expand(i, i+1);   // even-length palindromes (centre between i and i+1)
    }
    return s.slice(start, start + maxLen);
}
console.log(longestPalindrome('babad'));  // 'bab' or 'aba'
console.log(longestPalindrome('cbbd'));   // 'bb'

// PALINDROMIC SUBSTRINGS COUNT (#647) — count all palindromes
function countSubstrings(s) {
    let count = 0;
    function expand(left, right) {
        while (left >= 0 && right < s.length && s[left] === s[right]) {
            count++; left--; right++;
        }
    }
    for (let i = 0; i < s.length; i++) {
        expand(i, i);   // odd
        expand(i, i+1); // even
    }
    return count;
}
console.log(countSubstrings('abc'));  // 3 (a,b,c)
console.log(countSubstrings('aaa'));  // 6 (a,a,a,aa,aa,aaa)

// 2D DP APPROACH (for contrast) — O(n^2) time AND space
function longestPalindrome_DP(s) {
    const n = s.length;
    const dp = Array.from({length:n}, () => new Array(n).fill(false));
    let start = 0, maxLen = 1;

    // Base: single chars
    for (let i = 0; i < n; i++) dp[i][i] = true;
    // Base: two chars
    for (let i = 0; i < n-1; i++) {
        if (s[i] === s[i+1]) { dp[i][i+1] = true; start = i; maxLen = 2; }
    }
    // Length 3 and above
    for (let len = 3; len <= n; len++) {
        for (let i = 0; i <= n - len; i++) {
            const j = i + len - 1;
            if (s[i] === s[j] && dp[i+1][j-1]) {
                dp[i][j] = true;
                if (len > maxLen) { maxLen = len; start = i; }
            }
        }
    }
    return s.slice(start, start + maxLen);
}

